const userTurns = document.querySelectorAll(
  'section[data-testid^="conversation-turn-"][data-turn="user"]'
);

const assistantTurns = document.querySelectorAll(
  'section[data-testid^="conversation-turn-"][data-turn="assistant"]'
);

const turns = document.querySelectorAll(
  'section[data-testid^="conversation-turn-"][data-turn]'
);

if (turns.length === 0) {
  throw new Error(
    "未找到 ChatGPT 对话，请确认当前页面是聊天页面"
  );
}

automaSetVariable("chatgptPageCheck", {
  mountedTurns: turns.length,
  users: userTurns.length,
  assistants: assistantTurns.length,
  url: location.href
});

console.log(
  "[ChatGPT export] page check",
  {
    mountedTurns: turns.length,
    users: userTurns.length,
    assistants: assistantTurns.length
  }
);

const preview = text =>
  text.length > 30
    ? text.slice(0, 30) + "…"
    : text;

window.__chatgptCopiedText = null;
window.__chatgptCopySeq = 0;
window.__chatgptLastReadSeq = 0;

if (!window.__chatgptClipboardInstalled) {
  window.__chatgptClipboardInstalled = true;

  const clipboard = navigator.clipboard;
  window.__chatgptOriginalClipboardWriteText =
    clipboard?.writeText;

  window.__chatgptOriginalClipboardWrite =
    clipboard?.write;

  if (clipboard?.writeText) {
    clipboard.writeText = async function (text) {
      window.__chatgptCopiedText = text;
      window.__chatgptCopySeq++;

      console.log(
        "[ChatGPT export] writeText:",
        window.__chatgptCopySeq,
        preview(text)
      );

      // 不真正写入系统剪贴板
      return;
    };
  }

  if (clipboard?.write) {
    clipboard.write = async function (items) {
      console.log(
        "[ChatGPT export] write() called",
        items.length
      );

      for (const item of items) {
        if (!item.types?.includes("text/plain")) {
          continue;
        }

        const blob =
          await item.getType("text/plain");

        const text =
          await blob.text();

        window.__chatgptCopiedText = text;
        window.__chatgptCopySeq++;

        console.log(
          "[ChatGPT export] write:",
          window.__chatgptCopySeq,
          preview(text)
        );

        return;
      }

      console.warn(
        "[ChatGPT export] write() 中没有 text/plain"
      );
    };
  }
}

console.log(
  "[ChatGPT export] clipboard interceptor ready"
);

automaSetVariable("conversation", []);
automaSetVariable("currentTurnSelector", null);
automaSetVariable("currentTurnId", null);
automaSetVariable("currentTurnRole", null);
automaSetVariable("currentTurnNumber", null);
automaSetVariable("chatgptDone", false);
automaSetVariable("currentTurnFound", "no");

window.__chatgptSeen = new Set();
window.__chatgptIdleRounds = 0;

console.log(
  "[ChatGPT export] state initialized"
);

const turns = [
  ...document.querySelectorAll(
    'section[data-testid^="conversation-turn-"][data-turn][data-turn-id]'
  )
];

const getTurnNumber = el => {
  const testid =
    el.getAttribute("data-testid") || "";

  const match =
    testid.match(/conversation-turn-(\d+)/);

  return match
    ? Number(match[1])
    : Number.MAX_SAFE_INTEGER;
};

turns.sort(
  (a, b) =>
    getTurnNumber(a) - getTurnNumber(b)
);

let found = null;

for (const el of turns) {
  const id =
    el.getAttribute("data-turn-id");

  if (
    id &&
    !window.__chatgptSeen.has(id)
  ) {
    found = el;
    break;
  }
}

if (!found) {
  automaSetVariable(
    "currentTurnFound",
    "no"
  );

  automaSetVariable(
    "currentTurnSelector",
    ""
  );

  automaSetVariable(
    "currentTurnId",
    ""
  );

  automaSetVariable(
    "currentTurnRole",
    ""
  );

  automaSetVariable(
    "currentTurnNumber",
    ""
  );

  console.log(
    "[ChatGPT export] no new mounted turn"
  );
} else {
  const id =
    found.getAttribute("data-turn-id");

  const role =
    found.getAttribute("data-turn");

  const turnNumber =
    getTurnNumber(found);

  const selector =
    `section[data-turn-id="${CSS.escape(id)}"]`;

  automaSetVariable(
    "currentTurnFound",
    "yes"
  );

  automaSetVariable(
    "currentTurnSelector",
    selector
  );

  automaSetVariable(
    "currentTurnId",
    id
  );

  automaSetVariable(
    "currentTurnRole",
    role
  );

  automaSetVariable(
    "currentTurnNumber",
    turnNumber
  );

  console.log(
    "[ChatGPT export] next turn",
    {
      turnNumber,
      role,
      id,
      selector
    }
  );
}

const seq =
  window.__chatgptCopySeq || 0;

const lastSeq =
  window.__chatgptLastReadSeq || 0;

const text =
  window.__chatgptCopiedText;

if (seq <= lastSeq) {
  throw new Error(
    `本轮没有捕获到新的复制内容: seq=${seq}, last=${lastSeq}`
  );
}

if (typeof text !== "string") {
  throw new Error(
    "捕获到的复制内容不是字符串"
  );
}

const id =
  automaRefData(
    "variables",
    "currentTurnId"
  );

const role =
  automaRefData(
    "variables",
    "currentTurnRole"
  );

const turnNumber =
  automaRefData(
    "variables",
    "currentTurnNumber"
  );

if (!id) {
  throw new Error(
    "缺少 currentTurnId"
  );
}

if (
  role !== "user" &&
  role !== "assistant"
) {
  throw new Error(
    `无法识别 role: ${role}`
  );
}

const conversation =
  automaRefData(
    "variables",
    "conversation"
  ) || [];

conversation.push({
  role,
  content: text,
  turnId: id,
  turnNumber
});

window.__chatgptSeen.add(id);
window.__chatgptLastReadSeq = seq;

automaSetVariable(
  "conversation",
  conversation
);

console.log(
  "[ChatGPT export] consumed",
  {
    turnNumber,
    role,
    total: conversation.length
  }
);

const el = document.querySelector(
  '[data-scroll-root]'
);

if (!el) {
  throw new Error(
    "无法找到 ChatGPT scroll root"
  );
}

const before = el.scrollTop;

const distance = Math.max(
  el.clientHeight * 0.75,
  500
);

el.scrollBy({
  top: distance,
  behavior: "instant"
});

const after = el.scrollTop;

console.log(
  "[ChatGPT export] scroll down",
  {
    before,
    after,
    moved: after - before,
    distance,
    scrollHeight: el.scrollHeight,
    clientHeight: el.clientHeight,
    remaining:
      el.scrollHeight -
      el.clientHeight -
      after
  }
);

const el = document.querySelector(
  '[data-scroll-root]'
);

if (!el) {
  throw new Error(
    "无法找到 ChatGPT scroll root"
  );
}

const nearBottom =
  el.scrollTop + el.clientHeight >=
  el.scrollHeight - 120;

const mountedTurns = [
  ...document.querySelectorAll(
    'section[data-testid^="conversation-turn-"][data-turn][data-turn-id]'
  )
];

const hasUnseen =
  mountedTurns.some(turn => {
    const id =
      turn.getAttribute("data-turn-id");

    return (
      id &&
      !window.__chatgptSeen.has(id)
    );
  });

if (hasUnseen) {
  window.__chatgptIdleRounds = 0;
} else {
  window.__chatgptIdleRounds =
    (window.__chatgptIdleRounds || 0) + 1;
}

const done =
  nearBottom &&
  !hasUnseen &&
  window.__chatgptIdleRounds >= 3;

automaSetVariable(
  "chatgptDone",
  done
);

console.log(
  "[ChatGPT export] check done",
  {
    nearBottom,
    hasUnseen,
    idleRounds: window.__chatgptIdleRounds,
    done,
    scrollTop: el.scrollTop,
    scrollHeight: el.scrollHeight,
    clientHeight: el.clientHeight
  }
);

const selector =
  automaRefData(
    "variables",
    "currentTurnSelector"
  );

const id =
  automaRefData(
    "variables",
    "currentTurnId"
  );

const role =
  automaRefData(
    "variables",
    "currentTurnRole"
  );

const turnNumber =
  automaRefData(
    "variables",
    "currentTurnNumber"
  );

const el =
  document.querySelector(selector);

if (!el) {
  throw new Error(
    `找不到当前 turn: ${selector}`
  );
}

let content = "";

// user 优先取消息正文，不把操作栏混进去
const message =
  el.querySelector(
    `[data-message-author-role="${role}"]`
  );

if (message) {
  content = message.innerText.trim();
} else {
  content = el.innerText.trim();
}

const conversation =
  automaRefData(
    "variables",
    "conversation"
  ) || [];

conversation.push({
  role,
  content,
  turnId: id,
  turnNumber,
  copied: false
});

window.__chatgptSeen.add(id);

automaSetVariable(
  "conversation",
  conversation
);

console.log(
  "[ChatGPT export] fallback extracted",
  {
    turnNumber,
    role,
    total: conversation.length
  }
);

const clipboard = navigator.clipboard;

if (clipboard) {
  if (window.__chatgptOriginalClipboardWriteText) {
    clipboard.writeText =
      window.__chatgptOriginalClipboardWriteText;
  }

  if (window.__chatgptOriginalClipboardWrite) {
    clipboard.write =
      window.__chatgptOriginalClipboardWrite;
  }
}

window.__chatgptClipboardInstalled = false;

console.log(
  "[ChatGPT export] clipboard interceptor restored"
);
